// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(address depositor, uint256 amount, address to) public {
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(c));
        vm.assume(to != address(c));
        // only recipients with no code accept a plain transfer without reverting
        vm.assume(to.code.length == 0);
        amount = bound(amount, 1, 1 ether);

        vm.deal(depositor, amount + 1 ether);
        vm.prank(depositor);
        c.deposit{value: amount}();
        require(address(c).balance == amount, "setup failed");

        vm.prank(address(this)); // creator == msg.sender of setUp deployment
        c.migrateTo(to);

        assertTrue(address(c).balance == 0);
    }
}
